import sys
sys.path.insert(0, "/testbed")
import warnings
from functools import partial

from scrapy.utils.misc import is_generator_with_return_value, warn_on_generator_with_return_value


def gen_no_ret(arg1, arg2):
    yield {}


def gen_ret(arg1, arg2):
    yield {}
    return 1


class Holder:
    def meth_ret(self, arg1):
        yield {}
        return 1


def show(label, func):
    try:
        print(label, "->", repr(func()))
    except Exception as exc:
        print(label, "-> EXC", type(exc).__name__ + ":", exc)


def warn_messages(callable_):
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        warn_on_generator_with_return_value(None, callable_)
    return [str(w.message)[:70] for w in caught]


print("python", sys.version.split()[0])
show("A plain gen_ret (control)", lambda: is_generator_with_return_value(gen_ret))
show("B plain gen_no_ret (control)", lambda: is_generator_with_return_value(gen_no_ret))
show("C partial(gen_no_ret) [issue example]", lambda: is_generator_with_return_value(partial(gen_no_ret, arg1=42)))
show("D partial(gen_ret)", lambda: is_generator_with_return_value(partial(gen_ret, arg1=42)))
show("E partial(partial(gen_ret))", lambda: is_generator_with_return_value(partial(partial(gen_ret, 1), 2)))
show("F partial(bound method with return)", lambda: is_generator_with_return_value(partial(Holder().meth_ret, 1)))
show("G warn_on_generator_with_return_value(None, partial(gen_no_ret))", lambda: warn_messages(partial(gen_no_ret, arg1=42)))
show("H warn_on_generator_with_return_value(None, partial(gen_ret))", lambda: warn_messages(partial(gen_ret, arg1=42)))
EOF
